create function public.forward_canonical(v jsonb) returns text language plpgsql immutable set search_path=public as $$ declare r text;begin case jsonb_typeof(v) when 'object' then select '{'||coalesce(string_agg(to_jsonb(key)::text||':'||public.forward_canonical(value),',' order by key collate "C"),'')||'}' into r from jsonb_each(v);when 'array' then select '['||coalesce(string_agg(public.forward_canonical(value),',' order by ord),'')||']' into r from jsonb_array_elements(v) with ordinality x(value,ord);else r:=v::text;end case;return r;end $$;
create function public.forward_hash(d text,v jsonb) returns text language sql immutable set search_path=public as $$ select encode(sha256(convert_to(d||E'\n'||public.forward_canonical(v),'UTF8')),'hex') $$;
DO $$ declare definition text; begin select pg_get_functiondef('public.forward_write(uuid,uuid,text,uuid,jsonb)'::regprocedure) into definition; execute replace(definition,'public.shadow_hash(','public.forward_hash('); select pg_get_functiondef('public.forward_log(uuid,text,jsonb,text)'::regprocedure) into definition; execute replace(definition,'public.shadow_hash(','public.forward_hash('); end $$;
revoke all on function public.forward_canonical(jsonb),public.forward_hash(text,jsonb),public.forward_log(uuid,text,jsonb,text),public.forward_write(uuid,uuid,text,uuid,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.forward_write(uuid,uuid,text,uuid,jsonb) to service_role;